trait Visitor[A] { def visit(e: Expr): A }
sealed trait Expr { def accept[A](v: Visitor[A]): A }
case class Num(value: Double) extends Expr {
  def accept[A](v: Visitor[A]): A = v.visit(this)
}
object TaxVisitor extends Visitor[Double] {
  def visit(e: Expr): Double = e match {
    case Num(v)    => v * 0.19
    case Add(l, r) => visit(l) + visit(r)
  }
}
